<?php
require_once __DIR__.'/includes/functions.php';
require_admin();
$tab=$_GET['tab']??'overview';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try { verify_csrf(); $action=$_POST['action']??'';
  if($action==='save-settings'){
   foreach(['school_name','election_type','election_location','start_at','duration_minutes','school_vision','school_mission','about_text','contact_text','results_public','active_background'] as $k){$v=trim((string)($_POST[$k]??'')); if($k==='duration_minutes')$v=(string)max(1,(int)$v); if($k==='active_background')$v=(string)max(1,min(3,(int)$v)); save_setting($k,$v);}
   foreach(['school_logo'=>'logo','background_1'=>'bg1','background_2'=>'bg2','background_3'=>'bg3'] as $field=>$prefix){$path=upload_image($field,$prefix);if($path)save_setting($field,$path);}
   flash('Pengaturan berhasil disimpan.'); redirect('admin.php?tab=settings');
  }
  if($action==='save-candidate'){
   $id=(int)($_POST['id']??0);$num=max(1,(int)($_POST['candidate_number']??1));$name=trim($_POST['name']??'');$vision=trim($_POST['vision']??'');$mission=trim($_POST['mission']??'');if($name===''||$vision===''||$mission==='')throw new RuntimeException('Nama, visi, dan misi wajib diisi.');
   $old='';if($id){$q=db()->prepare('SELECT photo FROM candidates WHERE id=?');$q->execute([$id]);$old=(string)($q->fetchColumn()?:'');}$photo=upload_image('photo','candidate')??$old;
   if($id){$q=db()->prepare('UPDATE candidates SET candidate_number=?,name=?,photo=?,vision=?,mission=? WHERE id=?');$q->execute([$num,$name,$photo,$vision,$mission,$id]);}else{$q=db()->prepare('INSERT INTO candidates(candidate_number,name,photo,vision,mission) VALUES(?,?,?,?,?)');$q->execute([$num,$name,$photo,$vision,$mission]);}flash('Data kandidat disimpan.');redirect('admin.php?tab=candidates');
  }
  if($action==='delete-candidate'){$id=(int)$_POST['id'];$q=db()->prepare('DELETE FROM candidates WHERE id=?');$q->execute([$id]);flash('Kandidat dihapus. Jika sudah ada suara untuk kandidat ini, suara terkait ikut terhapus.','error');redirect('admin.php?tab=candidates');}
  if($action==='save-user'){$id=(int)($_POST['id']??0);$identifier=trim($_POST['identifier']??'');$name=trim($_POST['full_name']??'');$role=$_POST['role']??'student';$pw=(string)($_POST['password']??'');if(!$identifier||!$name||!in_array($role,['student','employee','admin','superadmin'],true))throw new RuntimeException('Lengkapi ID, nama, dan peran.');if($id){if($pw!==''){$q=db()->prepare('UPDATE users SET identifier=?,full_name=?,role=?,password_hash=? WHERE id=?');$q->execute([$identifier,$name,$role,password_hash($pw,PASSWORD_DEFAULT),$id]);}else{$q=db()->prepare('UPDATE users SET identifier=?,full_name=?,role=? WHERE id=?');$q->execute([$identifier,$name,$role,$id]);}}else{if(!$pw)throw new RuntimeException('Password wajib untuk pengguna baru.');$q=db()->prepare('INSERT INTO users(identifier,full_name,role,password_hash) VALUES(?,?,?,?)');$q->execute([$identifier,$name,$role,password_hash($pw,PASSWORD_DEFAULT)]);}flash('Data pemilih/pengguna disimpan.');redirect('admin.php?tab=voters');}
  if($action==='delete-user'){$id=(int)$_POST['id'];if($id===(int)current_user()['id'])throw new RuntimeException('Akun yang sedang digunakan tidak dapat dihapus.');$q=db()->prepare("DELETE FROM users WHERE id=? AND role IN ('student','employee')");$q->execute([$id]);flash('Pengguna dihapus.');redirect('admin.php?tab=voters');}
 }catch(Throwable $t){flash($t instanceof PDOException?'Operasi gagal. Periksa apakah ID sudah digunakan atau data terkait masih dipakai.':$t->getMessage(),'error');redirect('admin.php?tab='.$tab);}
}
$flash=get_flash();$editCandidate=null;if(isset($_GET['edit_candidate'])){$q=db()->prepare('SELECT * FROM candidates WHERE id=?');$q->execute([(int)$_GET['edit_candidate']]);$editCandidate=$q->fetch();}
$editUser=null;if(isset($_GET['edit_user'])){$q=db()->prepare('SELECT id,identifier,full_name,role FROM users WHERE id=?');$q->execute([(int)$_GET['edit_user']]);$editUser=$q->fetch();}
$candidates=db()->query('SELECT c.*, (SELECT COUNT(*) FROM votes v WHERE v.candidate_id=c.id) vote_count FROM candidates c ORDER BY candidate_number,id')->fetchAll();
$users=db()->query('SELECT id,identifier,full_name,role,has_voted,created_at FROM users ORDER BY role,full_name')->fetchAll();$totalVotes=(int)db()->query('SELECT COUNT(*) FROM votes')->fetchColumn();$voterCount=(int)db()->query("SELECT COUNT(*) FROM users WHERE role IN ('student','employee')")->fetchColumn();
