<?php if($tab==='overview'):?><div class="stats-grid"><div class="stat-card"><span>Total kandidat</span><strong><?=count($candidates)?></strong></div><div class="stat-card"><span>Total pemilih</span><strong><?=$voterCount?></strong></div><div class="stat-card"><span>Suara masuk</span><strong><?=$totalVotes?></strong></div><div class="stat-card"><span>Status</span><strong class="status-text"><?=e(['upcoming'=>'Belum mulai','active'=>'Berlangsung','finished'=>'Selesai'][election_status()])?></strong></div></div><section class="admin-panel"><h2>Ringkasan pemilihan</h2><p><b><?=e(setting('school_name'))?></b> · <?=e(setting('election_type'))?></p><p>Lokasi: <?=e(setting('election_location'))?></p><p>Mulai: <?=e(setting('start_at'))?> · Durasi: <?=e(setting('duration_minutes'))?> menit</p><a class="btn btn-primary" href="admin.php?tab=settings">Ubah pengaturan</a></section>
<?php elseif($tab==='settings'):?><section class="admin-panel"><form method="post" enctype="multipart/form-data" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save-settings"><label>Nama sekolah<input name="school_name" value="<?=e(setting('school_name'))?>" required></label><label>Jenis pemilihan<select name="election_type"><option <?=setting('election_type')==='Ketua OSIS'?'selected':''?>>Ketua OSIS</option><option <?=setting('election_type')==='Ketua MPK'?'selected':''?>>Ketua MPK</option></select></label><label>Lokasi pemilihan<input name="election_location" value="<?=e(setting('election_location'))?>"></label><label>Tanggal dan waktu mulai<input type="datetime-local" name="start_at" value="<?=e(date('Y-m-d\TH:i',strtotime((string)setting('start_at'))))?>" required></label><label>Durasi (menit)<input type="number" min="1" name="duration_minutes" value="<?=e(setting('duration_minutes'))?>" required></label><label>Visi sekolah<textarea name="school_vision" rows="3"><?=e(setting('school_vision'))?></textarea></label><label>Misi sekolah<textarea name="school_mission" rows="3"><?=e(setting('school_mission'))?></textarea></label><label>Tentang aplikasi<textarea name="about_text" rows="3"><?=e(setting('about_text'))?></textarea></label><label>Kontak<textarea name="contact_text" rows="3"><?=e(setting('contact_text'))?></textarea></label><label>Logo sekolah (JPG/PNG/WebP)<input type="file" name="school_logo" accept="image/png,image/jpeg,image/webp"></label><label>Publikasikan hasil<select name="results_public"><option value="1" <?=setting('results_public','1')==='1'?'selected':''?>>Ya</option><option value="0" <?=setting('results_public')==='0'?'selected':''?>>Tidak</option></select></label><div class="form-actions"><button class="btn btn-primary">Simpan pengaturan</button></div></form></section>
