<?php elseif($tab==='candidates'):?><section class="admin-panel"><h2><?=$editCandidate?'Edit kandidat':'Tambah kandidat'?></h2><form method="post" enctype="multipart/form-data" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save-candidate"><input type="hidden" name="id" value="<?=e($editCandidate['id']??'')?>"><label>Nomor kandidat<input type="number" min="1" name="candidate_number" value="<?=e($editCandidate['candidate_number']??(count($candidates)+1))?>"></label><label>Nama kandidat<input name="name" required value="<?=e($editCandidate['name']??'')?>"></label><label>Foto kandidat<input type="file" name="photo" accept="image/png,image/jpeg,image/webp"></label><label>Visi<textarea name="vision" required rows="3"><?=e($editCandidate['vision']??'')?></textarea></label><label>Misi<textarea name="mission" required rows="4"><?=e($editCandidate['mission']??'')?></textarea></label><div class="form-actions"><button class="btn btn-primary">Simpan kandidat</button><a class="btn btn-outline" href="admin.php?tab=candidates">Batal</a></div></form></section><section class="admin-panel"><h2>Daftar kandidat</h2><div class="table-wrap"><table><thead><tr><th>No.</th><th>Kandidat</th><th>Suara</th><th>Aksi</th></tr></thead><tbody><?php foreach($candidates as $c):?><tr><td><?=e($c['candidate_number'])?></td><td><div class="table-person"><img src="<?=e(image_url($c['photo']))?>" alt=""><b><?=e($c['name'])?></b></div></td><td><?=e($c['vote_count'])?></td><td><a class="text-link" href="admin.php?tab=candidates&edit_candidate=<?=$c['id']?>">Edit</a><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete-candidate"><input type="hidden" name="id" value="<?=$c['id']?>"><button class="text-danger">Hapus</button></form></td></tr><?php endforeach;?></tbody></table></div></section>
<?php elseif($tab==='voters'):?><section class="admin-panel"><h2><?=$editUser?'Edit akun':'Tambah pemilih/akun'?></h2><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save-user"><input type="hidden" name="id" value="<?=e($editUser['id']??'')?>"><label>ID / NIS / NIP<input name="identifier" required value="<?=e($editUser['identifier']??'')?>"></label><label>Nama lengkap<input name="full_name" required value="<?=e($editUser['full_name']??'')?>"></label><label>Peran<select name="role"><?php foreach(['student'=>'Siswa','employee'=>'Pegawai','admin'=>'Admin','superadmin'=>'Superadmin'] as $k=>$v):?><option value="<?=$k?>" <?=($editUser['role']??'student')===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><label>Password <?=$editUser?'(kosongkan jika tidak diubah)':''?><input type="password" name="password" <?=$editUser?'':'required'?>></label><div class="form-actions"><button class="btn btn-primary">Simpan akun</button></div></form></section><section class="admin-panel"><h2>Daftar akun</h2><div class="table-wrap"><table><thead><tr><th>ID</th><th>Nama</th><th>Peran</th><th>Status suara</th><th>Aksi</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?=e($u['identifier'])?></td><td><?=e($u['full_name'])?></td><td><?=e($u['role'])?></td><td><?=in_array($u['role'],['student','employee'],true)?($u['has_voted']?'Sudah memilih':'Belum memilih'):'—'?></td><td><a class="text-link" href="admin.php?tab=voters&edit_user=<?=$u['id']?>">Edit</a><?php if(in_array($u['role'],['student','employee'],true)):?><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete-user"><input type="hidden" name="id" value="<?=$u['id']?>"><button class="text-danger">Hapus</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><p class="muted">Demi keamanan, password tidak pernah ditampilkan dalam tabel.</p></section><?php endif;?></main></div></body></html>
